using System.Text.Json;
using RaidClipPlugin.Config;
using RaidClipPlugin.Models;
using RaidClipPlugin.Services;
using SnapshotProtocol;
using Xunit;
namespace RaidClipPlugin.Tests;
public sealed class RpgMythicRoleTests
{
 readonly RpgConfig c=new();
 readonly DateTimeOffset now=DateTimeOffset.Parse("2026-10-31T12:00:00Z");
 sealed class Low:IDuelRandom{public int NextInclusive(int min,int max)=>min;}
 sealed class High:IDuelRandom{public int NextInclusive(int min,int max)=>max;}
 static RpgProfile Wear(string set,int count=11){var p=new RpgProfile{PlayerLevel=80};foreach(var item in RpgMythicRoleCatalog.Items().Where(i=>i.SetId==set).Take(count)){p.Inventory.Add(item);p.Equipment[item.Slot!.Value]=item.InstanceId;}p.Health.CurrentHp=100;return p;}
 [Fact] public void TwoCompleteSetsSurviveValidationWithoutDuplicateOrRandomStats(){c.Validate();c.Validate();var all=c.DiveLoot.Items.Where(i=>RpgMythicRoleCatalog.IsSet(i.SetId)).ToArray();Assert.Equal(22,all.Length);foreach(var set in RpgMythicRoleCatalog.Sets()){var items=all.Where(i=>i.SetId==set.Id).ToArray();Assert.Equal(11,items.Length);Assert.Equal(11,items.Select(i=>i.Slot).Distinct().Count());Assert.All(items,i=>{Assert.Equal(ItemRarity.Mythic,i.Rarity);Assert.Equal(80,i.MinimumLevel);Assert.False(string.IsNullOrWhiteSpace(i.DisplayName));});var p=Wear(set.Id);Assert.True(RpgSetCombatService.Active(p,c.Sets,set.Id,11));Assert.False(RpgSetCombatService.Active(Wear(set.Id,10),c.Sets,set.Id,11));}var generated=RpgItemGenerationService.EnableForFutureDrops(c);Assert.All(generated.DiveLoot.Items.Where(i=>RpgMythicRoleCatalog.IsSet(i.SetId)),i=>Assert.Null(i.Generation));}
 [Fact] public void ClonedItemsDoNotCompleteSet(){var p=Wear(RpgMythicRoleCatalog.DamageSet,10);var clone=JsonSerializer.Deserialize<RpgItem>(JsonSerializer.Serialize(p.Inventory[9]))!;clone.InstanceId="clone";p.Inventory.Add(clone);p.Equipment[EquipmentSlot.Trinket2]=clone.InstanceId;Assert.False(RpgSetCombatService.Active(p,c.Sets,RpgMythicRoleCatalog.DamageSet,11));}
 [Fact] public void LootIsMythicDungeonOnlyAndRespectsLevel(){Assert.DoesNotContain(RpgMythicRoleCatalog.DungeonPool(c,79),i=>RpgMythicRoleCatalog.IsSet(i.SetId));Assert.Equal(22,RpgMythicRoleCatalog.DungeonPool(c,80).Count(i=>RpgMythicRoleCatalog.IsSet(i.SetId)));foreach(var boss in c.AreaBosses.Bosses)Assert.DoesNotContain(RpgLootLocations.BossPool(c,boss),i=>RpgMythicRoleCatalog.IsSet(i.SetId));Assert.All(RpgLootLocations.Build(c).Where(i=>RpgMythicRoleCatalog.IsSet(i.SetId)),i=>{Assert.NotEmpty(i.Sources);Assert.All(i.Sources,s=>Assert.Equal("dungeon",s.Kind));Assert.NotEmpty(i.Ranges);});}
 [Fact] public void StormRequiresCriticalFullSetAndPersistsCooldown(){var p=Wear(RpgMythicRoleCatalog.DamageSet);Assert.Equal(0,RpgMythicRoleCatalog.Storm(100,false,p,c,new(),now));Assert.Equal(250,RpgMythicRoleCatalog.Storm(100,true,p,c,new(),now));p=JsonSerializer.Deserialize<RpgProfile>(JsonSerializer.Serialize(p))!;Assert.Equal(0,RpgMythicRoleCatalog.Storm(100,true,p,c,new(),now.AddSeconds(7)));Assert.Equal(375,RpgMythicRoleCatalog.Storm(100,true,p,c,new(){WaterDamage=50},now.AddSeconds(8)));p.Equipment.Remove(EquipmentSlot.Belt);Assert.Equal(0,RpgMythicRoleCatalog.Storm(100,true,p,c,new(),now.AddSeconds(16)));}
 [Fact] public void HealerSetGrantsHealingAndOverhealShield(){var sender=Wear(RpgMythicRoleCatalog.HealerSet,9);var target=new RpgProfile();target.Health.CurrentHp=RpgHealthService.Maximum(target,c.Health);var entries=new Dictionary<string,ViewerPointEntry>{{"a",new(){Rpg=sender}},{"b",new(){Rpg=target}}};Assert.True(RpgGroupHealing.CanHeal(sender,c));var instance=new PartyInstance();Assert.Equal(0,RpgGroupHealing.Heal("a","b",100,instance,id=>entries[id],c,new High(),now));Assert.True(instance.Shields.GetValueOrDefault("b")>0);Assert.True(instance.Shields["b"]<=RpgHealthService.Maximum(target,c.Health)*c.Multiplayer.ShieldMaxHpPercent/100);}
 [Fact] public void EchoChoosesOtherLivingTargetAndCannotRepeatBeforeCooldown(){var entries=new Dictionary<string,ViewerPointEntry>{{"a",new(){Rpg=Wear(RpgMythicRoleCatalog.HealerSet)}},{"b",new(){Rpg=new()}},{"c",new(){Rpg=new()}},{"dead",new(){Rpg=new()}}};foreach(var e in entries.Values)e.Rpg.Health.CurrentHp=RpgHealthService.Maximum(e.Rpg,c.Health);entries["c"].Rpg.Health.CurrentHp=1;entries["dead"].Rpg.Health.CurrentHp=0;var party=new PartyState{Members=["a","b","c","dead"],Instance=new()};RpgGroupHealing.LifespringEcho("a","b",100,party,id=>entries[id],c,new High(),now);var healed=entries["c"].Rpg.Health.CurrentHp;Assert.True(healed>1);Assert.Equal(0,entries["dead"].Rpg.Health.CurrentHp);RpgGroupHealing.LifespringEcho("a","b",100,party,id=>entries[id],c,new High(),now.AddSeconds(1));Assert.Equal(healed,entries["c"].Rpg.Health.CurrentHp);Assert.Equal(now.AddSeconds(8),entries["a"].Rpg.Cooldowns["mythic:lifespring"]);}
 [Fact] public void CriticalHealingUsesEquipmentChance(){var p=Wear(RpgMythicRoleCatalog.HealerSet,6);var t=new RpgProfile();t.Health.CurrentHp=1;var entries=new Dictionary<string,ViewerPointEntry>{{"a",new(){Rpg=p}},{"b",new(){Rpg=t}}};var instance=new PartyInstance();RpgGroupHealing.Heal("a","b",10,instance,id=>entries[id],c,new Low(),now);Assert.Contains(instance.Log,x=>x.Action=="critical-heal");}
}
